frpm_conn = sqlite3.connect('/tmp/data_agent_structured_lzl5ydy5.sqlite')
frpm_cur = frpm_conn.cursor()
frpm_cur.execute("SELECT 'CDSCode', 'District Name', 'School Name', 'Charter Funding Type' FROM frpm WHERE 'District Name' LIKE '%Riverside%'")
frpm_rows = frpm_cur.fetchall()
frpm_conn.close()

cds_info = {}
for row in frpm_rows:
    cds, district, school, funding = row
    cds_info[cds] = {'district': district, 'school': school, 'funding': funding}

satscores_conn = sqlite3.connect('/home/tako/urp/react/data/public/input/task_199/context/db/satscores.db')
satscores_cur = satscores_conn.cursor()
riverside_cds = list(cds_info.keys())
cds_list = ','.join([f"'{cds}'" for cds in riverside_cds])
satscores_cur.execute(f"SELECT cds, AvgScrMath FROM satscores WHERE cds IN ({cds_list})")
sat_rows = satscores_cur.fetchall()
satscores_conn.close()

district_sums = {}
district_counts = {}
for cds, avg_math in sat_rows:
    if avg_math is not None:
        info = cds_info[cds]
        district = info['district']
        if district not in district_sums:
            district_sums[district] = 0
            district_counts[district] = 0
        district_sums[district] += avg_math
        district_counts[district] += 1

qualifying_districts = set()
for district in district_sums:
    avg = district_sums[district] / district_counts[district]
    if avg > 400:
        qualifying_districts.add(district)
        print(f"{district}: avg_math = {avg:.2f}")

result = []
for row in frpm_rows:
    cds, district, school, funding = row
    if district in qualifying_districts:
        result.append([district, school, funding])

print(f"\nTotal schools: {len(result)}")
for r in result[:10]:
    print(r)
